  };
  var EORDER = ["grunt", "runner", "wisp", "brute", "splitter", "mender"];
  var ETIDX = { grunt: 0, runner: 1, wisp: 2, brute: 3, splitter: 4, mender: 5, splitling: 6 };
  // hp, speed, bounty, leak, air, firstWave, weight
