    splitling: [0, 12, 1, 1, 0, 0, 0]
  };
  var SLOTS = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  function mkRoute(p) {
    var pts = [], cum = [0], i;
    for (i = 0; i < p.length; i++) pts.push([p[i][0] * 100 + 50, p[i][1] * 100 + 50]);
    for (i = 1; i < pts.length; i++) cum.push(cum[i - 1] + Math.abs(pts[i][0] - pts[i - 1][0]) + Math.abs(pts[i][1] - pts[i - 1][1]));
    return { pts: pts, cum: cum, len: cum[cum.length - 1] };
  }
  var GR = mkRoute([[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]]);
  var AR = mkRoute([[0,6],[21,6],[21,11],[23,11]]);
  function setPos(e) {
    var r = e.air ? AR : GR, d = e.progress, i = 0;
    while (i < r.cum.length - 2 && d >= r.cum[i + 1]) i++;
    var a = r.pts[i], b = r.pts[i + 1], t = d - r.cum[i];
    e.x = a[0] + (b[0] > a[0] ? t : b[0] < a[0] ? -t : 0);
    e.y = a[1] + (b[1] > a[1] ? t : b[1] < a[1] ? -t : 0);
    e.seg = i;
  }
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
  var rng = mulberry32(seed);
  var mm = [0, 1000];
  function mult(w) { while (mm.length <= w) mm.push(Math.floor(mm[mm.length - 1] * 108 / 100)); return mm[w]; }
  function armorOf(t, w) { return t === "grunt" ? Math.floor(w / 4) : t === "brute" ? 6 + w : 0; }
  var waves = {};
