            var u = slots[s]; if (!u || u.tier >= 3) continue;
            var uc = TT[u.type][0] * (u.tier === 1 ? 1 : 2); if (gold < uc) continue;
            gold -= uc; u.tier++; u.spent += uc; log.push([tick, "U", s, u.tier]);
          } else if (a.op === "sell") {
