// Parametric strategy factory: makeStrat(TYPES, SEQ, OPT) -> createStrategy
function makeStrat(TYPES, SEQ, OPT) {
  return function createStrategy() {
    var TN = ["bolt", "cannon", "frost", "lance", "flak"];
    var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
    var DMG = { bolt: [26, 41, 65], cannon: [60, 96, 153], frost: [10, 16, 25], lance: [180, 288, 460], flak: [40, 64, 102] };
    function plan(s) {
      var gold = s.gold, acts = [], tier = [], typ = [], want = [], i;
      for (i = 0; i < 16; i++) { var t = s.slots[i].turret; tier[i] = t ? t.tier : 0; typ[i] = t ? t.type : null; want[i] = 0; }
      for (i = 0; i < SEQ.length && acts.length < 32; i++) {
        var sl = SEQ[i]; want[sl]++;
        if (want[sl] > 3 || tier[sl] >= want[sl]) continue;
        var ty = TN[TYPES[sl]];
        if (typ[sl] && typ[sl] !== ty) continue;
        var cost = tier[sl] === 0 ? COST[ty] : COST[ty] * (tier[sl] === 1 ? 1 : 2);
        if (gold < cost) break;
        gold -= cost;
        acts.push(tier[sl] === 0 ? { op: "build", slot: sl, type: ty } : { op: "upgrade", slot: sl });
        tier[sl]++; typ[sl] = ty;
      }
      return acts;
    }
    function eff(type, tierN, e) {
      var d = DMG[type][tierN - 1];
      return type === "lance" ? d : Math.max(1, d - e.armor);
    }
    function target(t, c) {
      var n = c.length, i, j, best = null, bs = -Infinity;
      if (n === 1) return c[0].id;
      var ty = t.type;
      if (ty === "cannon" || ty === "flak") {
        var R = ty === "cannon" ? OPT.cr : OPT.fr;
        for (i = 0; i < n; i++) {
          var sc = 0, d = eff(ty, t.tier, c[i]);
          for (j = 0; j < n; j++) if (Math.abs(c[j].remaining - c[i].remaining) <= R) sc += Math.min(eff(ty, t.tier, c[j]), c[j].hp);
          sc = sc * 10000 - c[i].remaining;
          if (sc > bs) { bs = sc; best = c[i]; }
        }
        return best.id;
      }
      if (ty === "frost") {
        for (i = 0; i < n; i++) {
          var f = (c[i].slowed ? 0 : 1) * 1e6 + (c[i].type === "brute" || c[i].type === "mender" ? OPT.fb : 0) - c[i].remaining;
          if (f > bs) { bs = f; best = c[i]; }
        }
        return best.id;
      }
      if (ty === "lance") {
        for (i = 0; i < n; i++) {
          var dd = DMG.lance[t.tier - 1];
          var v = Math.min(dd, c[i].hp) * OPT.lw - c[i].remaining + (c[i].armor * OPT.la);
          if (v > bs) { bs = v; best = c[i]; }
        }
        return best.id;
      }
      // bolt
      for (i = 0; i < n; i++) {
        var e2 = eff("bolt", t.tier, c[i]);
        var v2 = Math.min(e2, c[i].hp) * OPT.bw - c[i].remaining + (c[i].type === "mender" ? OPT.mb : 0);
        if (v2 > bs) { bs = v2; best = c[i]; }
      }
      return best.id;
    }
    return { plan: plan, target: OPT.notarget ? undefined : target };
  };
}

