var args = typeof arguments !== 'undefined' ? arguments : [];
var RS = parseInt(args[0] || '1'), ITERS = parseInt(args[1] || '200'), NTRAIN = parseInt(args[2] || '10'), INIT = args[3] || '';
var r = RS * 7919 + 13;
function rnd() { r = (Math.imul(r, 1103515245) + 12345) | 0; return ((r >>> 8) & 0xffffff) / 0x1000000; }
function ri(n) { return Math.floor(rnd() * n); }
var G;
if (INIT) G = JSON.parse(INIT);
else G = {
  T: [0, 0, 2, 1, 3, 4, 1, 0, 3, 0, 3, 1, 4, 1, 4, 4],
  S: [3, 6, 0, 1, 4, 3, 12, 8, 6, 5, 13, 11, 10, 7, 9, 2, 14, 15, 4, 8, 12, 3, 6, 10, 13, 11, 0, 1, 2, 5, 7, 9, 14, 15, 4, 8, 3, 6, 12, 10, 13, 11, 0, 1, 2, 5, 7, 9, 14, 15],
  O: { cr: 60, fr: 50, fb: 50, lw: 3, la: 0, bw: 3, mb: 100 }
};
function evalG(g, seeds) {
  var cs = makeStrat(g.T, g.S, g.O), tot = 0, mn = 1e9;
  for (var i = 0; i < seeds.length; i++) { var sc = rampartSimulate(cs, seeds[i], 12020).score; tot += sc; if (sc < mn) mn = sc; }
  return tot / seeds.length;
}
var train = []; for (var i = 0; i < NTRAIN; i++) train.push(1000 + i * 37 + RS * 1000);
function clone(g) { return JSON.parse(JSON.stringify(g)); }
var t0 = Date.now();
var cur = evalG(G, train);
print('init', cur, (Date.now() - t0) + 'ms');
for (var it = 0; it < ITERS; it++) {
  var g = clone(G), m = ri(10);
  if (m < 2) { g.T[ri(16)] = ri(5); }
  else if (m < 5) { var a = ri(g.S.length), b = ri(g.S.length); var x = g.S[a]; g.S[a] = g.S[b]; g.S[b] = x; }
  else if (m < 8) { var a2 = ri(g.S.length), x2 = g.S.splice(a2, 1)[0]; g.S.splice(ri(g.S.length + 1), 0, x2); }
  else if (m < 9) { var a3 = ri(g.S.length - 1); var x3 = g.S[a3]; g.S[a3] = g.S[a3 + 1]; g.S[a3 + 1] = x3; }
  else { var ks = Object.keys(g.O), k = ks[ri(ks.length)]; g.O[k] = Math.max(0, Math.round(g.O[k] * (0.6 + rnd() * 0.8) + (rnd() - 0.5) * 20)); }
  var sc = evalG(g, train);
  if (sc >= cur) { if (sc > cur) print(it, sc.toFixed(3)); cur = sc; G = g; }
}
var val = []; for (i = 0; i < 20; i++) val.push(50000 + i * 101);
print('train', cur.toFixed(3), 'val', evalG(G, val).toFixed(3), 'time', (Date.now() - t0) / 1000);
print('BEST ' + JSON.stringify(G));

