function createStrategy() {
  "use strict";
  // Tuned offline by hill-climbing over many seeds (never seed 42).
  // TYPES: turret type per slot (0 bolt, 1 cannon, 2 frost, 3 lance, 4 flak).
  // SEQ: priority order of "advance this slot by one tier" steps; we save up for the next step when it is unaffordable.
  var TYPES = __T__;
  var SEQ = __S__;
  var OPT = __O__;
  var TN = ["bolt", "cannon", "frost", "lance", "flak"];
  var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  var DMG = { bolt: [26, 41, 65], cannon: [60, 96, 153], frost: [10, 16, 25], lance: [180, 288, 460], flak: [40, 64, 102] };
  function plan(s) {
    var gold = s.gold, acts = [], tier = [], typ = [], want = [], i;
    for (i = 0; i < 16; i++) {
      var t = s.slots[i] && s.slots[i].turret;
      tier[i] = t ? t.tier : 0; typ[i] = t ? t.type : null; want[i] = 0;
    }
    for (i = 0; i < SEQ.length && acts.length < 32; i++) {
      var sl = SEQ[i]; want[sl]++;
      if (want[sl] > 3 || tier[sl] >= want[sl]) continue;
      var ty = TN[TYPES[sl]];
      if (typ[sl] && typ[sl] !== ty) continue;
      var cost = tier[sl] === 0 ? COST[ty] : COST[ty] * (tier[sl] === 1 ? 1 : 2);
      if (gold < cost) break;
      gold -= cost;
      acts.push(tier[sl] === 0 ? { op: "build", slot: sl, type: ty } : { op: "upgrade", slot: sl });
      tier[sl]++; typ[sl] = ty;
    }
    return acts;
  }
  function eff(type, tierN, e) {
    var d = DMG[type][Math.max(1, Math.min(3, tierN)) - 1];
    return type === "lance" ? d : Math.max(1, d - (e.armor || 0));
  }
  // Only id / type / hp / armor / remaining / slowed are used, never positions.
  function target(t, c) {
    if (!c || !c.length) return undefined;
    var n = c.length, i, j, best = null, bs = -Infinity;
    if (n === 1) return c[0].id;
    var ty = t.type;
    if (ty === "cannon" || ty === "flak") {
      // aim at the densest cluster (by distance along the route), weighting by useful damage
      var R = ty === "cannon" ? OPT.cr : OPT.fr;
      for (i = 0; i < n; i++) {
        var sc = 0;
        for (j = 0; j < n; j++) if (Math.abs(c[j].remaining - c[i].remaining) <= R) sc += Math.min(eff(ty, t.tier, c[j]), c[j].hp);
        sc = sc * OPT.cs - c[i].remaining;
        if (sc > bs) { bs = sc; best = c[i]; }
      }
      return best.id;
    }
    if (ty === "frost") {
      for (i = 0; i < n; i++) {
        var f = (c[i].slowed ? 0 : 1) * 1e6 + (c[i].type === "brute" || c[i].type === "mender" ? OPT.fb : 0) + (c[i].type === "runner" ? OPT.fru : 0) - c[i].remaining;
        if (f > bs) { bs = f; best = c[i]; }
      }
      return best.id;
    }
    if (ty === "lance") {
      for (i = 0; i < n; i++) {
        var v = Math.min(DMG.lance[Math.max(1, Math.min(3, t.tier)) - 1], c[i].hp) * OPT.lw - c[i].remaining + (c[i].armor || 0) * OPT.la;
        if (v > bs) { bs = v; best = c[i]; }
      }
      return best.id;
    }
    for (i = 0; i < n; i++) {
      var v2 = Math.min(eff("bolt", t.tier, c[i]), c[i].hp) * OPT.bw - c[i].remaining + (c[i].type === "mender" ? OPT.mb : 0);
      if (v2 > bs) { bs = v2; best = c[i]; }
    }
    return best.id;
  }
  return { plan: plan, target: target };
}

