load('x_sim.js'); load('x_strategy.js');
var A = function () { return { plan: function (s) { var a = [], g = s.gold; for (var i = 0; i < s.slots.length; i++) { var sl = s.slots[i]; if (!sl.turret && g >= 50) { a.push({ op: "build", slot: sl.slot, type: "bolt" }); g -= 50; } } return a; } }; };
var r = rampartSimulate(A, 42, 12020);
print('A', r.score, r.fallTick, r.log.length, r.hash, r.score === 25.38 && r.fallTick === 1035 && r.log.length === 166 && r.hash === '82a5353d' ? 'MATCH' : 'MISMATCH');
var B = function () { return { plan: function (s) {
  if (s.wave === 1) return [{ op: "build", slot: 3, type: "cannon" }, { op: "build", slot: 6, type: "frost" }];
  if (s.wave === 3) return [{ op: "upgrade", slot: 3 }, { op: "build", slot: 12, type: "flak" }];
  if (s.wave === 6) return [{ op: "build", slot: 8, type: "lance" }, { op: "sell", slot: 6 }];
  return []; } }; };
r = rampartSimulate(B, 7, 12020);
print('B', r.score, r.fallTick, r.log.length, r.hash, r.score === 10.93 && r.fallTick === 457 && r.log.length === 48 && r.hash === '2e8858d7' ? 'MATCH' : 'MISMATCH');
var s42 = rampartSimulate(createStrategy, 42, 2020);
print('seed42 replay', s42.score, s42.fallTick, s42.hash);
var s42full = rampartSimulate(createStrategy, 42, 12020);
print('seed42 full', s42full.score);
// independence: two strategy objects must not share state
var o1 = createStrategy(), o2 = createStrategy(); print('fresh objects', o1 !== o2 && o1.plan !== o2.plan);
var seeds = []; for (var i = 0; i < 100; i++) seeds.push(300000 + i * 7717);
var tot = 0, mn = 1e9, mx = 0, t0 = Date.now(), worst = 0;
seeds.forEach(function (sd) { var t1 = Date.now(); var x = rampartSimulate(createStrategy, sd, 12020).score; worst = Math.max(worst, Date.now() - t1); tot += x; mn = Math.min(mn, x); mx = Math.max(mx, x); });
print('100 seeds mean', (tot / 100).toFixed(3), 'min', mn, 'max', mx, 'worst ms/game', worst, 'total ms', Date.now() - t0);
var few = [1, 2, 3, 7, 1234]; print('seeds 1,2,3,7,1234:', few.map(function (sd) { return rampartSimulate(createStrategy, sd, 12020).score; }).join(' '));

